Definition own_regions (C : lctx) (A : AS) (s : Z) (R : list (Z * Z)) : Prop :=
  Forall (fun r => (c_top C - LSTK <= fst r /\ fst r + snd r <= s)
                   \/ exists (p : word) n, live A p = Some n /\ live (c_A0 C) p = None /\ u p <= fst r /\ fst r + snd r <= u p + n) R.

