(* [comment removed for export] *)
Lemma POSTM_bracket : forall C Ar A A' m mD mh mE md md' (s s' c : Z) (n : nat) (RD RE : list (Z * Z)) (bs : list byte) (p : word) (np : Z),
  Cok C -> W C A m md -> W C A' mh md' -> sub_live Ar A -> sub_live A A' -> s' <= s -> s <= c_top C ->
  live A p = Some np -> u p <= c -> c + Z.of_nat n <= u p + np -> length bs = n ->
  rinv (RD ++ [(c, Z.of_nat n)]) m mD -> local_regions C A Ar s RD ->
  POSTM C A s' mD mh ->
  rinv (RE ++ [(c, Z.of_nat n)]) mh mE -> local_regions C A' Ar s RE ->
  rdn segs m (Z_to_bv 64 c) n = Some bs -> rdn segs mE (Z_to_bv 64 c) n = Some bs ->
  POSTM C Ar s m mE.
Proof.
