(* [comment removed for export] *)
Lemma bracket_rdn : forall A (m mD mh mE : word -> option byte) (s' : Z) C (RD RE : list (Z * Z)) (q : word) (k x : Z) (n : nat),
  rinv RD m mD -> POSTM C A s' mD mh -> rinv RE mh mE -> live A q = Some k -> u q <= x -> x + Z.of_nat n <= u q + k -> u q + k <= 2 ^ 64 ->
  (forall r, In r (RD ++ RE) -> x + Z.of_nat n <= fst r \/ fst r + snd r <= x) ->
  rdn segs mE (Z_to_bv 64 x) n = rdn segs m (Z_to_bv 64 x) n.
Proof.
