(* [comment removed for export] *)
Lemma POSTM_of_footprint : forall C A m md m' (sk cellp clen s' : Z), Cok C -> W C A m md ->
  (forall a : word, ~ scratch C sk a -> ~ (cellp <= u a < cellp + clen) -> m' a = m a) ->
