Definition LIVKc (A : AS) (c n : Z) (m m' : word -> option byte) : Prop :=
  forall q k i, live A q = Some k -> 0 <= i < k -> ~ (c <= u q + i < c + n) -> m' (at_ q i) = m (at_ q i).
Definition POSTMc (C : lctx) (A : AS) (s c n : Z) (m m' : word -> option byte) : Prop := FRM C s m m' /\ LIVKc A c n m m'.

