Lemma rinv_WPc : forall C Ar A m md M' (R : list (Z * Z)) (s c n : Z) (p : word) (np : Z), Cok C -> W C A m md -> sub_live Ar A -> s <= c_top C ->
  live A p = Some np -> live (c_A0 C) p = None -> u p <= c -> c + n <= u p + np ->
  rinv R m M' ->
  Forall (fun r => (c_top C - LSTK <= fst r /\ fst r + snd r <= s) \/ (c <= fst r /\ fst r + snd r <= c + n)
                   \/ exists (q : word) k, live A q = Some k /\ live Ar q = None /\ live (c_A0 C) q = None /\ u q <= fst r /\ fst r + snd r <= u q + k) R ->
  W C A M' md /\ POSTMc C Ar s c n m M'.
